template <class F> auto map_stage(F f) {
    return [f](auto rf) { return [f, rf](auto acc, auto const& x) { return rf(acc, f(x)); }; };
}
template <class P> auto filter_stage(P pred) {
    return [pred](auto rf) { return [pred, rf](auto acc, auto const& x) { return pred(x) ? rf(acc, x) : acc; }; };
}
